"""Shared oracle library for the PyJWT unsupported-crit-extension task.

Both `test_output.py` and `test.sh` (the weighted grading launcher) use this
module. It owns every extract/patch/install/replay primitive so the grading
logic in `test_output.py` stays a thin set of assertions over these helpers,
and so there is exactly one place that knows how to extract the pristine
tree, apply a submitted patch, install it editable, and replay a JWS token
through the project's own decode path.

This module never trusts anything written by the agent's own container: it
extracts its own copy of the pristine (vulnerable) source from the
base64-embedded archive below, held out from the agent's image, and only
reads the single file the harness contract declares as gradeable,
PATCH_PATH.
"""

from __future__ import annotations

import ast
import base64
import hashlib
import hmac
import io
import json
import os
import shutil
import subprocess
import sys

try:
    import pwd
except ImportError:  # non-POSIX; the oracle then installs without dropping
    pwd = None
import tarfile
import tempfile
from pathlib import Path

TASK_DIR = Path(__file__).resolve().parent

# The pristine, unpatched (vulnerable) source snapshot, base64-embedded here
# rather than shipped as a separate data/src.tgz file so the verifier bundle
# keeps to the standard layout.
#
# DELIBERATE DIVERGENCE, do not "sync" this against environment/src.tgz. The two
# archives agree on 92 of 93 files; run_poc.py is intentionally different. The
# copy inside environment/src.tgz is sanitized, because it ships in the agent's
# image: its docstring and its verdict lines name no advisory, no CVE, no RFC
# section and no CWE, all of which would hand over the answer. The copy embedded
# here is the annotated original, and it is what restore_immutable() writes back
# into a patched tree and what stage_harness() replays through, both of which
# live verifier-side and are never visible to the agent.
#
# This is safe only because nothing grades the harness's stdout: run_poc() is
# consumed through its return code alone (0 rejected, 1 accepted), which both
# copies produce identically, and the stage assertions in test_output.py read
# `run.returncode` and put `run.stdout` in failure messages only. Two things
# follow. Never add a check that digest-compares the two run_poc.py copies, it
# would fire on an intentional difference. And never write a stage that asserts
# on harness output text, it would be asserting against a transcript the agent
# never saw. solution/crash.log is the annotated harness's transcript, held
# out with every other piece of evidence: the agent's image ships none.
