OUTPUT_DIR = Path(os.environ.get("OUTPUT_DIR", "/output"))
PATCH_PATH = OUTPUT_DIR / "fix.patch"
SUBMITTED_POC_PATH = OUTPUT_DIR / "poc.bin"

REPO_DIR_NAME = "pyjwt"
PACKAGE_RELATIVE_PATH = "jwt"
VULNERABLE_SOURCE_RELATIVE_PATH = "jwt/api_jws.py"
RUN_POC_RELATIVE_PATH = "run_poc.py"
# Mirrors environment/config/config.toml's immutable_files. Declaring a path
# immutable and penalising an edit to it is not the same as enforcing it, so
# restore_immutable() below puts these back after a submitted patch is applied.
IMMUTABLE_RELATIVE_PATHS = (RUN_POC_RELATIVE_PATH,)
CONTROL_POC_SHA256 = (
    "5b34732abad9adfd91f69cd5549970d552c879400dce2576793021ee5b4db883"
)
GROUND_TRUTH_POC_SHA256 = (
    "ebbbc38a11d712e8ed6b549c399bbb90dbccd68cdae402bb0f97d9783a6563ae"
)

PATCH_TIMEOUT = 15
INSTALL_TIMEOUT = 120
RUN_TIMEOUT = 30
TEST_TIMEOUT = 300

# A fresh, unpredictable root per grading run. The editable install executes the
# submission's build step, and a fixed path like /tmp/pyjwt_crit_oracle is one a
# build hook can write into before the oracle first looks there. Randomising is
# not the defence on its own, since a hook could enumerate the parent, it just
# removes the cheapest aim. The defences that do not depend on secrecy are
# stage_harness() rewriting unconditionally and stage_evidence() verifying.
WORK_DIR = Path(os.environ.get("ORACLE_WORK_DIR")
                or tempfile.mkdtemp(prefix="pyjwt_crit_oracle_"))
# The reproduction harness is staged here, outside every tree under test.
HARNESS_DIR = WORK_DIR / "harness"
# The embedded reproducers are decoded to here, also outside every tree.
EVIDENCE_DIR = WORK_DIR / "evidence"

CONTROL_POC_PATH = EVIDENCE_DIR / "given_poc.bin"
GROUND_TRUTH_POC_PATH = EVIDENCE_DIR / "poc.bin"

_EMBEDDED_POCS = {
    CONTROL_POC_PATH: (CONTROL_POC_B64, CONTROL_POC_SHA256),
    GROUND_TRUTH_POC_PATH: (GROUND_TRUTH_POC_B64, GROUND_TRUTH_POC_SHA256),
}

_TREE_CACHE: dict = {}


def sha256_file(path) -> str:
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def materialize_poc(poc_path: Path) -> Path:
    """Decode an embedded reproducer to disk, unconditionally, and verify it.

    Written every call rather than only when absent, for the same reason
    stage_harness() rewrites unconditionally: an is_file() shortcut would let a
    build hook that got there first have the oracle replay its own bytes.
    """
    poc_path = Path(poc_path)
    encoded, expected = _EMBEDDED_POCS[poc_path]
    raw = base64.b64decode(encoded)
    digest = hashlib.sha256(raw).hexdigest()
    if digest != expected:
        raise RuntimeError(
            f"embedded reproducer for {poc_path.name} decodes to digest {digest}, "
            f"not the locked {expected}; the constant in this module was edited"
        )
    poc_path.parent.mkdir(parents=True, exist_ok=True)
    poc_path.write_bytes(raw)
    return poc_path


for _poc_path in _EMBEDDED_POCS:
    materialize_poc(_poc_path)


def parse_diff(patch_text: str):
    """Return (touched relative paths, added-line count, removed-line count)."""
    touched = set()
    added = 0
    removed = 0
    for line in patch_text.splitlines():
        if line.startswith("+++ ") or line.startswith("--- "):
            candidate = line[4:].strip().split("\t")[0]
            if candidate in ("/dev/null", ""):
                continue
            if candidate.startswith(("a/", "b/")):
                candidate = candidate[2:]
            touched.add(candidate)
        elif line.startswith("+") and not line.startswith("+++"):
            added += 1
        elif line.startswith("-") and not line.startswith("---"):
            removed += 1
    return touched, added, removed


def _extract_pristine(dest_dir: Path) -> Path:
    if dest_dir.exists():
        shutil.rmtree(dest_dir)
    dest_dir.mkdir(parents=True)
    with tarfile.open(fileobj=io.BytesIO(base64.b64decode(PRISTINE_SRC_TGZ_B64))) as archive:
        archive.extractall(dest_dir)
    return dest_dir / REPO_DIR_NAME


def restore_immutable(repo_dir: Path) -> list:
    """Overwrite the declared-immutable paths with their pristine content.

    The reproduction harness is the instrument the replay stages measure with,
    and a submitted patch is applied to the same tree it lives in. Without this
    restore, a patch that rewrites run_poc.py to report a rejection banks both
    replay stages while repairing nothing: the negative-weight check charges it
    -5 but the forged stages are worth +10. Restoring the file leaves the
    penalty in place and takes the payout away.
    """
    restored = []
    with tarfile.open(fileobj=io.BytesIO(base64.b64decode(PRISTINE_SRC_TGZ_B64))) as archive:
        for relpath in IMMUTABLE_RELATIVE_PATHS:
            member = archive.extractfile(f"{REPO_DIR_NAME}/{relpath}")
            if member is None:
                continue
            target = repo_dir / relpath
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(member.read())
            restored.append(relpath)
    return restored


def _patch_paths_are_contained(patch_text: str) -> bool:
    """Every target in the diff stays inside the tree, read without stripping.

    Only consulted before falling back to -p0, where the recorded path is used
    as written. GNU patch refuses absolute and parent-relative names on its own,
    but that is its behaviour rather than a contract, so the fallback is offered
    only for a diff that does not need it.
    """
    touched, _, _ = parse_diff(patch_text)
    for path in touched:
        if path.startswith("/") or path.startswith("~"):
            return False
        if ".." in Path(path).parts:
            return False
    return bool(touched)


def _strip_level(repo_dir: Path, patch_path: Path) -> str:
    """Pick the strip level this diff was written for, without touching the tree.

    instruction.md asks for paths relative to the repo dir, which describes both
    the `git diff` default (a/jwt/... , read with -p1) and `git diff
    --no-prefix` (jwt/... , read with -p0). Committing to one silently scores a
    correct repair as a failure to apply, so both are probed with --dry-run and
    the tree is only written once the right level is known. -p1 is tried first
    and is what a failure is reported against, since it is the common form.
    """
    for level in ("1", "0"):
        if level == "0" and not _patch_paths_are_contained(
                patch_path.read_text(encoding="utf-8", errors="replace")):
            break
        probe = subprocess.run(
            ["patch", f"-p{level}", "--forward", "--dry-run", "-i", str(patch_path)],
            cwd=str(repo_dir), stdin=subprocess.DEVNULL,
            timeout=PATCH_TIMEOUT, capture_output=True, text=True,
        )
        if probe.returncode == 0:
            return level
    return "1"


def apply_patch(repo_dir: Path, patch_path: Path):
    """Apply the submitted diff, never interactively.

    GNU patch prompts on stdin when a diff names a path it considers dangerous,
    a traversal or a path through a symlink, and it asks again per hunk. Left
    with an inherited stdin the call would block until PATCH_TIMEOUT, or worse
    read whatever the grading launcher happens to have there. DEVNULL makes it
    answer its own prompt with EOF and skip, which is the verdict wanted anyway.
    """
    level = _strip_level(repo_dir, patch_path)
    return subprocess.run(
        ["patch", f"-p{level}", "--forward", "-i", str(patch_path)],
        cwd=str(repo_dir), stdin=subprocess.DEVNULL,
        timeout=PATCH_TIMEOUT, capture_output=True, text=True,
    )


BUILD_USER = os.environ.get("ORACLE_BUILD_USER", "qcbuild")


def build_identity():
    """The unprivileged identity the editable install runs as, or None.

    None means there is nothing to drop to, either because this process is
    already unprivileged or because the image ships no such account, and the
    install then runs as the current user exactly as it used to.
    """
    if pwd is None or not hasattr(os, "geteuid") or os.geteuid() != 0:
        return None
    try:
        entry = pwd.getpwnam(BUILD_USER)
    except KeyError:
        return None
    return entry.pw_uid, entry.pw_gid


def _install(repo_dir: Path):
    """Editable-install the extracted tree.

    --no-build-isolation is required, not an optimisation: the task runs with
    allow_internet=false, and PEP 517 build isolation would try to fetch this
    project's build backend (setuptools>=77.0.3) from PyPI into a throwaway
    environment even though the image already ships it. With no network that
    fetch fails and every downstream stage fails with it. The Dockerfile
    installs setuptools and wheel so this call has the backend to hand.
    """
    command = [sys.executable, "-m", "pip", "install", "-q", "--no-cache-dir",
               "--no-build-isolation", "-e", "."]
    env = dict(os.environ)
    identity = build_identity()
    extra = {}
    if identity is not None:
        uid, gid = identity
        # The work root becomes traversable so the build account can reach its
        # own copy, and stays unwritable so it cannot leave anything beside it.
        WORK_DIR.chmod(0o711)
        userbase = repo_dir.parent / (repo_dir.name + "_userbase")
        userbase.mkdir(parents=True, exist_ok=True)
        for path in (repo_dir, userbase):
            subprocess.run(["chown", "-R", f"{uid}:{gid}", str(path)],
                           stdin=subprocess.DEVNULL, timeout=PATCH_TIMEOUT,
                           capture_output=True)
        env["HOME"] = str(repo_dir)
        env["PYTHONUSERBASE"] = str(userbase)
        command.append("--user")
        extra = {"user": uid, "group": gid}
    return subprocess.run(
        command, cwd=str(repo_dir), env=env, stdin=subprocess.DEVNULL,
        timeout=INSTALL_TIMEOUT, capture_output=True, text=True, **extra,
    )


def _install_in_sandbox(repo_dir: Path):
    """Editable-install a copy, so the build step never runs in the graded tree.

    `pip install -e .` executes the project's own build, which the submission
    controls. Handing it a copy means whatever it does to its tree is discarded
    with that copy, and the tree the replay and the probes read was never given
    to it. Nothing downstream needs the install to resolve the package: the
    replay and the probes append the tree to sys.path themselves, and the
    project suite runs with the tree as its working directory.
    """
    sandbox = Path(str(repo_dir) + "_install")
    if sandbox.exists():
        shutil.rmtree(sandbox)
    shutil.copytree(repo_dir, sandbox)
    return _install(sandbox)


def get_or_build_tree(patch_path):
    """Extract, optionally patch, and editable-install once for a given
    patch identity (None = pristine/vulnerable). patch_path is either None
    (grade the pristine tree) or PATCH_PATH (grade the agent's submission).
    Passing the constant explicitly, rather than a bare boolean, keeps every
    call site self-describing about which artifact it depends on.
    """
    key = str(patch_path) if patch_path is not None else None
    if key in _TREE_CACHE:
        return _TREE_CACHE[key]
    scratch = WORK_DIR / ("patched_tree" if patch_path is not None else "vuln_tree")
    repo_dir = _extract_pristine(scratch)
    patch_result = None
    if patch_path is not None:
        patch_result = apply_patch(repo_dir, patch_path)
        # Enforce, do not merely penalise: the harness the stages replay through
        # must be this module's copy, never the submission's.
        restore_immutable(repo_dir)
    install_result = _install_in_sandbox(repo_dir)
    _TREE_CACHE[key] = (repo_dir, patch_result, install_result)
    return _TREE_CACHE[key]


def stage_harness() -> Path:
    """Write the pristine reproduction harness outside every tree under test.

    The instrument must not live inside the specimen. A submitted patch is
    applied to the tree, and its build hooks execute inside that tree when the
    editable install runs, which is after restore_immutable() has already put
    the in-tree harness back. Replaying through a copy the submission can never
    reach closes that whole ordering question rather than racing it.
    """
    HARNESS_DIR.mkdir(parents=True, exist_ok=True)
    harness = HARNESS_DIR / RUN_POC_RELATIVE_PATH
    # Written unconditionally, never adopted if already present. A lazy
    # is_file() shortcut here is a pre-seeding hole: stage_harness() is first
    # reached after the editable install has run, so a build hook that creates
    # this file first would have the oracle replay the submission's own harness.
    with tarfile.open(fileobj=io.BytesIO(base64.b64decode(PRISTINE_SRC_TGZ_B64))) as archive:
        member = archive.extractfile(f"{REPO_DIR_NAME}/{RUN_POC_RELATIVE_PATH}")
        harness.write_bytes(member.read())
    return harness


LOCKED_POC_DIGESTS = {
    CONTROL_POC_PATH: CONTROL_POC_SHA256,
    GROUND_TRUTH_POC_PATH: GROUND_TRUTH_POC_SHA256,
}


def stage_evidence(poc_path: Path) -> Path:
    """Verify a reproducer against its locked digest, then stage a private copy.

    A stage that checks the digest at its top and reads the file at its bottom
    leaves a window, because the editable install runs in between and executes
    the submission's build step. Replaying a copy taken after the check means
    the bytes that were verified are the bytes that run.
    """
    poc_path = Path(poc_path)
    if poc_path in _EMBEDDED_POCS:
        materialize_poc(poc_path)
    digest = sha256_file(poc_path)
    expected = LOCKED_POC_DIGESTS.get(poc_path)
    if expected is not None and digest != expected:
        raise RuntimeError(
            f"reproducer {poc_path} has digest {digest}, not the locked {expected}; "
            "refusing to replay tampered evidence"
        )
    HARNESS_DIR.mkdir(parents=True, exist_ok=True)
    staged = HARNESS_DIR / f"evidence_{digest[:16]}.bin"
    staged.write_bytes(poc_path.read_bytes())
    return staged


def _isolated(script: str, stdin_text: str):
    """Run the probe under the isolation every replay and probe shares.

    -S keeps interpreter startup hooks out: a patch whose build step drops a
    .pth into site-packages would otherwise run code on every interpreter this
    module starts. The working directory is the staged harness dir rather than
    the tree, and the tree is appended to sys.path by the probe itself rather
    than placed on PYTHONPATH, so the standard library always resolves first and
    a module dropped into the repo root cannot shadow one a probe relies on.

    The directory is created here rather than assumed, because an e2e submission
    that ships no poc.bin makes the earlier stages assert before anything stages
    the harness, and a probe that then dies on a missing cwd would report a
    crash where the oracle owes a verdict.
    """
    HARNESS_DIR.mkdir(parents=True, exist_ok=True)
    return subprocess.run(
        [sys.executable, "-S", "-c", script], input=stdin_text,
        cwd=str(HARNESS_DIR), timeout=RUN_TIMEOUT, capture_output=True, text=True,
    )


# One probe script, byte-identical for every question this module asks. What
# differs between a control decode, a b64 round trip and the unsupported-name
# family arrives on stdin, never in the command line.
#
# That uniformity is the point. The probe imports the package under test, so the
# submission's own code runs inside this process and can read /proc/self/cmdline.
# If each question carried its own script text, that code could tell which
# question it was being asked and print the answer the oracle wanted without
# decoding anything. With one script and the request on stdin, the process
# cannot separate the token it must reject from the token it must accept without
# actually examining them, which is the work being graded.
UNIFORM_PROBE_SCRIPT = """
import sys, json
_req = json.loads(sys.stdin.read())
sys.path.append(_req["repo"])
import jwt
from jwt.exceptions import InvalidTokenError
_out = {}
for _name, _token in sorted(_req.get("decode", {}).items()):
    try:
        _claims = jwt.decode(_token, _req["secret"], algorithms=["HS256"])
    except InvalidTokenError as _exc:
        _out[_name] = {"accepted": False, "error": type(_exc).__name__}
    except Exception as _exc:
        _out[_name] = {"accepted": False, "error": "unexpected:" + type(_exc).__name__}
    else:
        _out[_name] = {"accepted": True, "claims": _claims}
if _req.get("b64_roundtrip"):
    try:
        _payload = b"attached-probe-payload"
        _token = jwt.api_jws.encode(
            _payload, _req["secret"], algorithm="HS256",
            headers={"crit": ["b64"], "b64": False}, is_payload_detached=True,
        )
        _back = jwt.api_jws.decode(
            _token, _req["secret"], algorithms=["HS256"], detached_payload=_payload,
        )
        _out["b64_roundtrip"] = {"accepted": _back == _payload}
    except Exception as _exc:
        _out["b64_roundtrip"] = {"accepted": False, "error": type(_exc).__name__}
sys.stdout.write("QC-VERDICT:" + json.dumps(_out, sort_keys=True) + chr(10))
sys.stdout.flush()
"""

VERDICT_TAG = "QC-VERDICT:"


def probe(repo_dir: Path, request: dict):
    """Ask the uniform probe a question. Returns its answer, or None.

    None means the probe did not answer cleanly: a non-zero exit, no tagged
    line, more than one tagged line, or output that is not the JSON object this
    module asked for. Every caller treats None as a failure to grade rather than
    as a passing verdict, so injected chatter cannot read as an answer.
    """
    payload = dict(request)
    payload["repo"] = str(repo_dir)
    payload.setdefault("secret", "secret")
    run = _isolated(UNIFORM_PROBE_SCRIPT, json.dumps(payload))
    if run.returncode != 0:
        return None
    tagged = [line[len(VERDICT_TAG):] for line in run.stdout.splitlines()
              if line.startswith(VERDICT_TAG)]
    if len(tagged) != 1:
        return None
    try:
        answer = json.loads(tagged[0])
    except ValueError:
        return None
    return answer if isinstance(answer, dict) else None


def run_poc(repo_dir: Path, poc_path: Path):
    """Replay one reproducer through the project's own harness.

    The harness is the staged copy outside the tree, and the reproducer is the
    verified copy stage_evidence() took, so neither the instrument nor the
    evidence is something the submission can reach.
    """
    harness = stage_harness()
    evidence = stage_evidence(poc_path)
    return _isolated(
        "import sys, runpy\n"
        f"sys.path.append({str(repo_dir)!r})\n"
        f"sys.argv = [{RUN_POC_RELATIVE_PATH!r}, {str(evidence)!r}]\n"
        f"runpy.run_path({str(harness)!r}, run_name='__main__')\n",
        "",
    )


def replay_is_corroborated(repo_dir: Path, poc_path: Path) -> bool:
    """Does the uniform probe agree that this reproducer is rejected?

    The harness invocation is the one call this module makes that a submission
    can recognise, because runpy names the harness on the command line. Asking
    the uniform probe the same question closes that: the probe is
    indistinguishable from the control and family probes, so code that fakes a
    rejection for the harness has to fake it for every probe too, and then the
    control token it must accept is rejected as well.
    """
    token = Path(poc_path).read_bytes().decode("ascii").strip()
    answer = probe(repo_dir, {"decode": {"replay": token}})
    if answer is None:
        return False
    return answer.get("replay", {}).get("accepted") is False


def run_project_tests(repo_dir: Path):
    return subprocess.run(
        [sys.executable, "-m", "pytest", "-q", "tests/"],
        cwd=str(repo_dir), stdin=subprocess.DEVNULL,
        timeout=TEST_TIMEOUT, capture_output=True, text=True,
    )


def make_token(header: dict, payload: dict, secret: bytes = b"secret") -> str:
    """Build a compact JWS with raw hmac/base64/json.

    Deliberately independent of the library under test: a token minted by the
    patched build would inherit whatever the patch did to the encode path, and
    could not then be used to judge the decode path.
    """
    def seg(obj):
        return base64.urlsafe_b64encode(
            json.dumps(obj, separators=(",", ":"), sort_keys=True).encode()
        ).rstrip(b"=")

    signing_input = seg(header) + b"." + seg(payload)
    signature = base64.urlsafe_b64encode(
        hmac.new(secret, signing_input, hashlib.sha256).digest()
    ).rstrip(b"=")
    return (signing_input + b"." + signature).decode("ascii")


def functional_digest(repo_dir: Path) -> str:
    """Digest the parsed form of every module in the package.

    Comments, blank lines and formatting drop out of an AST dump, so two trees
    share a digest exactly when they differ by nothing an interpreter would act
    on. That is what separates a repair from a submission which applies cleanly,
    installs and leaves behaviour untouched.
    """
    package = repo_dir / PACKAGE_RELATIVE_PATH
    digest = hashlib.sha256()
    for path in sorted(package.rglob("*.py")):
        digest.update(path.relative_to(package).as_posix().encode())
        try:
            dump = ast.dump(ast.parse(path.read_text(encoding="utf-8", errors="replace")))
        except SyntaxError:
            dump = "<unparseable>"
        digest.update(dump.encode())
    return digest.hexdigest()


SUPPORTED_CRIT_EXTENSIONS = frozenset({"b64"})

NETWORK_MODULES = frozenset({
    "socket", "ssl", "urllib", "urllib.request", "http", "http.client",
    "requests", "httpx", "ftplib", "smtplib", "telnetlib", "xmlrpc",
    "subprocess", "asyncio.subprocess",
})


def compact_header(raw: bytes):
    """The JOSE header of a compact JWS, or None if these bytes are not one.

    Parsed here rather than through the library, because the question asked of
    it is whether a submission's reproducer engages the defect, and the library
    under test is the thing whose behaviour is in question.
    """
    try:
        segment = raw.decode("ascii").strip().split(".")[0]
    except (UnicodeDecodeError, AttributeError):
        return None
    try:
        decoded = base64.urlsafe_b64decode(segment + "=" * (-len(segment) % 4))
        header = json.loads(decoded)
    except Exception:
        return None
    return header if isinstance(header, dict) else None


def crit_engagement(header) -> tuple:
    """Does this header put the crit contract in question? (verdict, detail).

    True for anything RFC 7515 4.1.11 requires a recipient to refuse: a crit
    naming an extension outside the supported set, a crit that is not a
    non-empty list of strings, or a named extension absent from the header. False
    only for a token with no crit at all, or one whose crit names nothing but
    extensions the library implements and carries each of them -- which is a
    token the library is supposed to accept, so accepting it evidences nothing.
    """
    if header is None:
        return False, "not a compact JWS with a JSON object header"
    if "crit" not in header:
        return False, "header carries no crit parameter"
    crit = header["crit"]
    if not isinstance(crit, list):
        return True, f"crit is {type(crit).__name__}, not a list"
    if not crit:
        return True, "crit is an empty list"
    non_strings = [c for c in crit if not isinstance(c, str)]
    if non_strings:
        return True, f"crit carries non-string members {non_strings!r}"
    unsupported = [c for c in crit if c not in SUPPORTED_CRIT_EXTENSIONS]
    if unsupported:
        return True, f"crit names unsupported extension(s) {unsupported!r}"
    absent = [c for c in crit if c not in header]
    if absent:
        return True, f"crit names {absent!r} but the header does not carry them"
    return False, (f"crit names only supported extensions {crit!r}, all present in "
                   f"the header, which the library is meant to accept")


def _package_modules(repo_dir: Path):
    for path in sorted((repo_dir / PACKAGE_RELATIVE_PATH).rglob("*.py")):
        try:
            yield (path.relative_to(repo_dir).as_posix(),
                   ast.parse(path.read_text(encoding="utf-8", errors="replace")))
        except (SyntaxError, ValueError):
            continue


def _tally(pairs) -> dict:
    counts: dict = {}
    for key in pairs:
        counts[key] = counts.get(key, 0) + 1
    return counts


def _dotted(node) -> str:
    parts = []
    while isinstance(node, ast.Attribute):
        parts.append(node.attr)
        node = node.value
    if isinstance(node, ast.Name):
        parts.append(node.id)
    return ".".join(reversed(parts))


def suppression_sites(repo_dir: Path) -> dict:
    """Exception suppression in the package, counted per module and kind.

    Read off the AST rather than off the diff text, so reformatting, renaming
    the caught class, or spreading `except Exception: pass` across lines does
    not change the answer. Counted rather than located, because a patch shifts
    line numbers and the question is only whether a submission added any.
    """
    found = []
    for rel, tree in _package_modules(repo_dir):
        for node in ast.walk(tree):
            if isinstance(node, ast.ExceptHandler):
                if node.type is None:
                    found.append((rel, "bare-except"))
                body = node.body
                if all(isinstance(stmt, ast.Pass) for stmt in body):
                    found.append((rel, "except-pass"))
                elif (len(body) == 1 and isinstance(body[0], ast.Expr)
                        and isinstance(body[0].value, ast.Constant)
                        and body[0].value.value is Ellipsis):
                    found.append((rel, "except-ellipsis"))
            elif isinstance(node, (ast.With, ast.AsyncWith)):
                for item in node.items:
                    call = item.context_expr
                    if isinstance(call, ast.Call) and _dotted(call.func).endswith("suppress"):
                        found.append((rel, "contextlib-suppress"))
    return _tally(found)


def network_sites(repo_dir: Path) -> dict:
    """Network- and process-reaching references, counted per module and name.

    An import of `socket` and a call to `urlopen` are both recorded, so a
    submission that reaches out through an aliased import is caught alongside
    one that spells the call out.
    """
    found = []
    for rel, tree in _package_modules(repo_dir):
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    root = alias.name.split(".")[0]
                    if alias.name in NETWORK_MODULES or root in NETWORK_MODULES:
                        found.append((rel, "import", alias.name))
            elif isinstance(node, ast.ImportFrom):
                module = node.module or ""
                root = module.split(".")[0]
                if module in NETWORK_MODULES or root in NETWORK_MODULES:
                    found.append((rel, "import-from", module))
            elif isinstance(node, ast.Call):
                name = _dotted(node.func)
                tail = name.rsplit(".", 1)[-1]
                if tail in ("urlopen", "urlretrieve", "getaddrinfo", "connect",
                            "Popen", "check_output", "check_call"):
                    found.append((rel, "call", tail))
    return _tally(found)


def added_sites(pristine: dict, patched: dict) -> dict:
    """Keys the patched tree has more of than the pristine one."""
    return {key: patched[key] - pristine.get(key, 0)
            for key in patched if patched[key] > pristine.get(key, 0)}


_BEHAVIOUR_CACHE: dict = {}


def behaviour_report(patch_path):
    """One cached snapshot of how a submitted patch behaves, built once.

    This module is the only place in the bundle that knows how to turn a diff
    into a built tree and interrogate it, and this function is where every such
    question is asked. Callers in test_output.py -- the stages that grade a
    rejection and the cheat detectors that charge a crude one -- read answers
    out of the dict returned here instead of building or probing a tree of their
    own. Three things follow.

    The work happens once per grading run rather than once per caller. The
    control token and the b64 round trip travel in a single probe request, so
    what used to be up to seven probe subprocesses across the module is now one,
    and the two replays behind `inert` are the only other processes needed.

    Every graded assertion downstream becomes a pure function of the submitted
    diff plus these answers. A cheat detector's whole input is PATCH_PATH: it
    reads the artifact the agent produced and this report, and reaches for no
    tree, no scratch directory and no path of its own.

    And the questions are asked identically no matter who is asking. A stage
    that needs a precondition and a detector that charges the same condition
    read the same field of the same cached dict, so the two can never disagree
    about what the build did.

    Keys, each paired with a *_detail string naming what was observed so a
    caller can explain a verdict without repeating the work:

      built         the diff applied and the editable install succeeded
      control_ok    a token carrying no crit array at all still decodes
      roundtrip_ok  a detached payload still round trips under crit ["b64"],
                    the one critical extension the library implements
      inert         the patch leaves the library answering the reproducer
                    exactly as the pristine tree does, judged both on the
                    package's parsed form and on the replay verdict
      added_suppression  exception suppression the patched package's AST carries
                    and the pristine one does not
      added_network exports to the network or to a subprocess the patched
                    package's AST carries and the pristine one does not

    patch_path is the submitted diff (PATCH_PATH). `inert` is meaningful only
    against a patch, since it compares the patched tree with the pristine one.
    """
    key = str(patch_path)
    if key in _BEHAVIOUR_CACHE:
        return _BEHAVIOUR_CACHE[key]

    repo_dir, patch_result, install_result = get_or_build_tree(patch_path)
    patch_rc = None if patch_result is None else patch_result.returncode
    install_rc = install_result.returncode
    built = patch_rc in (None, 0) and install_rc == 0

    unbuilt = "the patched tree did not build"
    report = {
        "built": built,
        "patch_returncode": patch_rc,
        "install_returncode": install_rc,
        "install_stderr": install_result.stderr[-800:],
        "control_ok": False,
        "control_detail": unbuilt,
        "roundtrip_ok": False,
        "roundtrip_detail": unbuilt,
        "inert": False,
        "inert_detail": unbuilt,
        "replay_unchanged": False,
        "added_suppression": {},
        "added_suppression_detail": unbuilt,
        "added_network": {},
        "added_network_detail": unbuilt,
    }
    if not built:
        _BEHAVIOUR_CACHE[key] = report
        return report

    # Both questions ride in one request. The probe script is byte-identical for
    # every question this module asks, so asking them together costs one process
    # and gives the submission's own code no way to tell them apart.
    control = make_token(
        {"alg": "HS256", "typ": "JWT"}, {"sub": "control", "role": "user"}
    )
    answer = probe(repo_dir, {"decode": {"control": control}, "b64_roundtrip": True})
    if answer is None:
        report["control_detail"] = "PROBE-FAILED"
        report["roundtrip_detail"] = "PROBE-FAILED"
    else:
        decoded = answer.get("control", {})
        if not decoded.get("accepted"):
            report["control_detail"] = (
                f"CONTROL-REJECTED {decoded.get('error', 'unknown')}"
            )
        elif decoded.get("claims", {}).get("sub") != "control":
            report["control_detail"] = "CONTROL-WRONG"
        else:
            report["control_ok"] = True
            report["control_detail"] = "CONTROL-OK"

        roundtrip = answer.get("b64_roundtrip", {})
        if roundtrip.get("accepted"):
            report["roundtrip_ok"] = True
            report["roundtrip_detail"] = "ROUNDTRIP-OK"
        else:
            report["roundtrip_detail"] = (
                f"ROUNDTRIP-RAISED {roundtrip.get('error', 'unknown')}"
            )

    # Inert means the parsed form is unchanged: a comment-only or whitespace-only
    # diff handed in as a repair. The replay verdict is recorded but deliberately
    # excluded -- a patch that moves the digest yet leaves the reproducer accepted
    # is a repair that missed, not a sham, and stage 2, stage 4 and the crit-family
    # tests already price it at 18 of the 24 positive points. Charging it here too
    # put an honest partial repair below the zero an empty submission scores. Do
    # not restore the replay clause.
    pristine_dir, _, pristine_install = get_or_build_tree(None)
    if pristine_install.returncode != 0:
        report["inert_detail"] = "the pristine tree did not build"
    else:
        pristine_digest = functional_digest(pristine_dir)
        patched_digest = functional_digest(repo_dir)
        pristine_rc = run_poc(pristine_dir, CONTROL_POC_PATH).returncode
        patched_rc = run_poc(repo_dir, CONTROL_POC_PATH).returncode
        report["inert"] = (pristine_digest == patched_digest)
        report["replay_unchanged"] = (pristine_rc == patched_rc)
        report["inert_detail"] = (
            f"parsed form pristine {pristine_digest[:12]} against patched "
            f"{patched_digest[:12]}, and replay exit pristine {pristine_rc} "
            f"against patched {patched_rc}"
        )

        # Differential, not absolute: the package already imports and catches
        # things of its own, and only what a submission adds is chargeable.
        suppression = added_sites(suppression_sites(pristine_dir),
                                  suppression_sites(repo_dir))
        report["added_suppression"] = suppression
        report["added_suppression_detail"] = (
            f"added {sorted(suppression.items())}" if suppression
            else "no exception suppression beyond the pristine package"
        )
        network = added_sites(network_sites(pristine_dir), network_sites(repo_dir))
        report["added_network"] = network
        report["added_network_detail"] = (
            f"added {sorted(network.items())}" if network
            else "no network or subprocess reach beyond the pristine package"
        )

    _BEHAVIOUR_CACHE[key] = report
    return report


def selfcheck() -> int:
    """Confirm the bundled pristine archive extracts and the vulnerable
    source is present, without installing anything. Exercised by
    tests/test.sh as a fast preflight before the full oracle runs."""
    with tempfile.TemporaryDirectory() as tmp:
        repo_dir = _extract_pristine(Path(tmp) / "selfcheck_tree")
        if not (repo_dir / VULNERABLE_SOURCE_RELATIVE_PATH).is_file():
            print(f"selfcheck: {VULNERABLE_SOURCE_RELATIVE_PATH} missing from pristine tree")
            return 1
        if not (repo_dir / RUN_POC_RELATIVE_PATH).is_file():
            print(f"selfcheck: {RUN_POC_RELATIVE_PATH} missing from pristine tree")
            return 1
    for label, path, locked in (
        ("control", CONTROL_POC_PATH, CONTROL_POC_SHA256),
        ("ground-truth", GROUND_TRUTH_POC_PATH, GROUND_TRUTH_POC_SHA256),
    ):
        try:
            materialize_poc(path)
        except (RuntimeError, ValueError, KeyError) as exc:
            print(f"selfcheck: {label} reproducer does not materialise: {exc}")
            return 1
        digest = sha256_file(path)
        if digest != locked:
            print(f"selfcheck: {label} reproducer at {path} digest {digest} "
                  f"no longer matches the locked {locked}")
            return 1
    if sha256_file(CONTROL_POC_PATH) == sha256_file(GROUND_TRUTH_POC_PATH):
        print("selfcheck: the held-out reproducer is a copy of the control token, "
              "so the inert cheat check and stage 4 measure the same thing")
        return 1
    print("selfcheck: pristine archive present, control and held-out reproducers "
          "embedded and locked")
    return 0


if __name__ == "__main__":
    sys.exit(selfcheck())
